120	// `prefix` filters candidate basenames; empty accepts any executable. The
121	// default verilator/build scan passes "sim_"; a user-curated engines dir passes
122	// "" so a drop-in alioth/sid (any name) is eligible. The naming convention thus
123	// lives in the call site, not in this engine-agnostic scanner.
124	void scan_dir(const fs::path& dir, std::string_view prefix, Discovery& out,
125	              std::set<std::string>& seen) {
126	  std::error_code ec;
127	  if (!fs::is_directory(dir, ec)) return;
128	
129	  std::vector<fs::path> entries;
130	  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
131	  std::sort(entries.begin(), entries.end());  // stable, deterministic order
132	
133	  for (const fs::path& p : entries) {
134	    if (!prefix.empty() && !p.filename().string().starts_with(prefix)) continue;
135	    if (!is_executable_file(p)) continue;
136	    EngineDescriptor d;
137	    std::string warn;
138	    if (describe_one(p, d, warn)) {
139	      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
140	    } else if (!warn.empty()) {
141	      out.warnings.push_back(warn);
142	    }
143	  }
144	}
