148	Discovery discover_engines() {
149	  Discovery out;
150	  std::set<std::string> seen;
151	
152	  EngineDescriptor qemu = builtin_qemu();
153	  seen.insert(qemu.id);
154	  out.engines.push_back(std::move(qemu));
155	
156	  if (const char* env = std::getenv("ANDES_SIM_ENGINES_DIR"); env && *env) {
157	    std::stringstream ss(env);
158	    std::string dir;
159	    while (std::getline(ss, dir, ':'))
160	      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
161	  } else {
162	    scan_dir(repo_root() / "verilator" / "build", /*prefix=*/"sim_", out, seen);
163	  }
164	  return out;
